style.css:
/* Общие стили для тёмной темы */
body {
    background-color: #121212; /* Темный фон */
    color: #e0e0e0; /* Светлый текст */
}

/* Ссылки */
a {
    color: #bb86fc; /* Цвет ссылок */
}


a:hover {
    color: #3700b3; /* Цвет ссылок при наведении */
}

